request_id = ContextVar("request_id", default="-")

@app.middleware("http")
async def correlate(request, call_next):
    token = request_id.set(request.headers.get("x-request-id") or str(uuid4()))
    try:
        return await call_next(request)
    finally:
        request_id.reset(token)
